cases.bad:
// SW-side only
try { request = await h.requestPermission({mode:'read'}) } catch {}
// returns 'prompt' — no dialog possible in SW → verifyPermission false → []

cases.good:
// extension-page provider ensure before delegating to SW
if ((await handle.queryPermission({mode:'read'})) === 'granted') return;
if (navigator.userActivation && !navigator.userActivation.isActive) return;
await verifyPermission(handle, 'read');  // page has real activation → silent auto-grant
